#!/usr/bin/env node
/**
 * Build everything chromokit ships from its sources.
 *
 *     node scripts/build.mjs           write dist/, _extensions/chromokit/ and the R package's generated files
 *     node scripts/build.mjs --check   write nothing; exit 1 if any of them is out of date
 *
 * Sources: tokens/*.json (the values), src/css (the core components and the
 * standalone page), src/js (behaviours), adapters/<host> (what each framework
 * needs on top), lib/marks.mjs (the logo marks).
 *
 * Outputs are committed, so that a copy, a CDN link, `quarto add` or
 * `pak::pak()` gets them without running anything; CI runs `--check` so a
 * source change cannot land without its outputs.
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { markSvg } from '../lib/marks.mjs'
import { paletteCss } from '../lib/selectors.mjs'

const ROOT = resolve(fileURLToPath(new URL('..', import.meta.url)))
const CHECK = process.argv.includes('--check')
const pkg = JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8'))
const VERSION = pkg.version
const REPO = 'https://github.com/js2264/chromokit'

const read = (path) => readFileSync(join(ROOT, path), 'utf8')
const json = (path) => JSON.parse(read(path))
const listFiles = (dir) => {
  const out = []
  const walk = (here) => {
    for (const name of readdirSync(join(ROOT, here)).sort()) {
      const path = join(here, name)
      if (statSync(join(ROOT, path)).isDirectory()) walk(path)
      else out.push(path)
    }
  }
  if (existsSync(join(ROOT, dir))) walk(dir)
  return out
}

/** Everything the build writes: path relative to the repository → contents. */
const outputs = new Map()
const emit = (path, contents) => {
  if (outputs.has(path)) throw new Error(`two outputs for ${path}`)
  outputs.set(path, contents)
}

/** The roots the build owns: anything in them it did not write is stale. */
const OWNED = ['dist', '_extensions/chromokit', 'r/inst/pkgdown', 'r/R/tokens.R']

const STAMP = `chromokit ${VERSION} · MIT · ${REPO} · generated by scripts/build.mjs — do not edit; put local changes in your own stylesheet`
const cssHeader = `/*! ${STAMP} */\n`
const jsHeader = `/*! ${STAMP} */\n`

// ---------------------------------------------------------------- tokens

const app = json('tokens/chromosomix.json')
const code = json('tokens/code.json')
const kit = json('tokens/kit.json')

/** `rgb(24 24 26 / 7%)` → `#18181a12`: one spelling every Sass compiler takes. */
function hexAlpha(value) {
  return value.replace(/rgba?\(\s*(\d+)[\s,]+(\d+)[\s,]+(\d+)\s*(?:[/,]\s*([\d.]+)(%?))?\s*\)/g, (_, r, g, b, a, pct) => {
    const hex = (n) => Number(n).toString(16).padStart(2, '0')
    let alpha = ''
    if (a !== undefined) {
      const fraction = pct ? Number(a) / 100 : Number(a)
      alpha = hex(Math.round(fraction * 255))
    }
    return `#${hex(r)}${hex(g)}${hex(b)}${alpha}`
  })
}

const pxToRem = (px) => Number.parseFloat(px) / 16
const remCalc = (rem) => `calc(${Number(rem.toFixed(4))} * var(--cx-rem))`

const svgUri = (svg) => `url("data:image/svg+xml;charset=utf-8,${svg.replace(/"/g, "'").replace(/#/g, '%23')}")`
const ICON_URIS = {
  'icon-chevron': svgUri(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>`,
  ),
  'icon-link': svgUri(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/></svg>`,
  ),
  'terminal-dots': svgUri(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 60 16"><circle cx="8" cy="8" r="8"/><circle cx="30" cy="8" r="8"/><circle cx="52" cy="8" r="8"/></svg>`,
  ),
}

/** The values that do not change with the palette. */
const base = {
  rem: '1rem',
  sans: app.base.sans,
  mono: app.base.mono,
  radius: app.base.radius,
  'step--2': remCalc(Number.parseFloat(app.base['step--2'])),
  'step--1': remCalc(Number.parseFloat(app.base['step--1'])),
  'step-0': remCalc(Number.parseFloat(app.base['step-0'])),
  'step-1': remCalc(Number.parseFloat(app.base['step-1'])),
  'step-2': remCalc(Number.parseFloat(app.base['step-2'])),
  'step-3': remCalc(Number.parseFloat(app.base['step-3'])),
  label: remCalc(pxToRem(kit.prose.label)),
  ...Object.fromEntries(Object.entries(kit.layout).map(([name, value]) => [name, value])),
  'prose-size': remCalc(pxToRem(kit.prose.size)),
  'prose-line': kit.prose.line,
  'prose-h1': remCalc(pxToRem(kit.prose.h1)),
  'prose-h2': remCalc(pxToRem(kit.prose.h2)),
  'prose-h3': remCalc(pxToRem(kit.prose.h3)),
  'prose-h4': remCalc(pxToRem(kit.prose.h4)),
  'prose-h5': remCalc(pxToRem(kit.prose.h5)),
  ...ICON_URIS,
}

/** One palette, every name it sets, in a stable order. */
function palette(mode) {
  const out = { ...app.color[mode] }
  for (const [name, value] of Object.entries(app.shadow[mode])) out[name] = hexAlpha(value)
  for (const [name, value] of Object.entries(code[mode])) {
    out[['bg', 'fg', 'dots'].includes(name) ? `code-${name}` : `hl-${name}`] = value
  }
  kit.categorical[mode].forEach((value, index) => {
    out[`series-${index + 1}`] = value
  })
  return out
}
const LIGHT = palette('light')
const DARK = palette('dark')

const declarations = (values) =>
  Object.entries(values)
    .map(([name, value]) => `  --cx-${name}: ${value};`)
    .join('\n')

const tokensCss = [
  cssHeader,
  `/* Tokens. Light and dark palettes from chromosomix (${app.source.commit.slice(0, 7)}), syntax colours`,
  '   from Vitesse, page measures from chromokit. Every name is `--cx-<name>`. */',
  '',
  `:root {\n${declarations(base)}\n}`,
  '',
  paletteCss(declarations(LIGHT), declarations(DARK)),
  '',
].join('\n')

// ---------------------------------------------------------------- css

/**
 * Author in rem, ship relative to `--cx-rem`: a host whose root is not 16px
 * (zensical's is 20) sets `--cx-rem` and every component keeps its size. Media
 * queries cannot read a custom property, so their lines are left as written.
 */
function hostRelative(css) {
  return css
    .split('\n')
    .map((line) =>
      /^\s*@(media|container|supports)/.test(line) || /^\s*--cx-rem\s*:/.test(line)
        ? line
        : line.replace(/(?<![\w.-])(\d*\.?\d+)rem\b/g, (_, n) => `calc(${n} * var(--cx-rem))`),
    )
    .join('\n')
}

const componentSources = listFiles('src/css/components').filter((path) => path.endsWith('.css'))
const componentsCss = hostRelative(componentSources.map((path) => read(path).trim()).join('\n\n'))
const pageCss = hostRelative(read('src/css/page.css').trim())

const bundle = (...parts) => `${cssHeader}${parts.map((part) => part.replace(/^\/\*![^\n]*\*\/\n/, '').trim()).join('\n\n')}\n`

emit('dist/css/tokens.css', tokensCss)
emit('dist/css/components.css', bundle(componentsCss))
emit('dist/css/page.css', bundle(pageCss))
emit('dist/css/chromokit.css', bundle(tokensCss, componentsCss))
emit('dist/css/chromokit-page.css', bundle(tokensCss, componentsCss, pageCss))

// ---------------------------------------------------------------- js

const theme = read('src/js/theme.js')
const keys = read('src/js/keys.js')
const behaviours = read('src/js/behaviours.js')
emit('dist/js/theme.js', jsHeader + theme)
emit('dist/js/keys.js', jsHeader + keys)
emit('dist/js/behaviours.js', jsHeader + behaviours)
emit('dist/js/chromokit.js', `${jsHeader}${keys}\n${behaviours}`)

// ---------------------------------------------------------------- tokens as data

const raw = {
  version: VERSION,
  source: app.source,
  light: LIGHT,
  dark: DARK,
  base: {
    sans: app.base.sans,
    mono: app.base.mono,
    radius: app.base.radius,
    steps: Object.fromEntries(Object.entries(app.base).filter(([name]) => name.startsWith('step'))),
    layout: kit.layout,
    prose: kit.prose,
  },
  series: { light: kit.categorical.light, dark: kit.categorical.dark },
}
emit('dist/tokens/tokens.json', `${JSON.stringify(raw, null, 2)}\n`)
emit(
  'dist/tokens/tokens.mjs',
  `${jsHeader}/** chromokit's tokens as data: for a canvas, a chart library, or anything that cannot read CSS. */\nexport const tokens = ${JSON.stringify(raw, null, 2)}\n\nexport const light = tokens.light\nexport const dark = tokens.dark\nexport default tokens\n`,
)

// Sass: the palettes as maps and plain variables, for Bootstrap, pkgdown and Quarto.
const scssValue = (value) => (/[,()]/.test(value) && !value.startsWith('#') ? `unquote("${value.replace(/"/g, '\\"')}")` : value)
const scssMap = (values) =>
  `(\n${Object.entries(values)
    .map(([name, value]) => `  "${name}": ${scssValue(value)}`)
    .join(',\n')}\n)`
const scssVars = (values, suffix) =>
  Object.entries(values)
    .map(([name, value]) => `$cx-${name}-${suffix}: ${scssValue(value)} !default;`)
    .join('\n')
emit(
  'dist/scss/_tokens.scss',
  [
    `// ${STAMP}`,
    '',
    `$cx-version: "${VERSION}";`,
    `$cx-sans: ${app.base.sans} !default;`,
    `$cx-mono: ${app.base.mono} !default;`,
    `$cx-radius: ${app.base.radius} !default;`,
    '',
    `$cx-light: ${scssMap(LIGHT)} !default;`,
    '',
    `$cx-dark: ${scssMap(DARK)} !default;`,
    '',
    scssVars(LIGHT, 'light'),
    '',
    scssVars(DARK, 'dark'),
    '',
    '@function cx($name, $mode: light) {',
    '  @if $mode == dark {',
    '    @return map-get($cx-dark, $name);',
    '  }',
    '  @return map-get($cx-light, $name);',
    '}',
    '',
  ].join('\n'),
)

// brand.yml: Quarto (1.6+), Shiny and bslib read it.
const brand = (mode) => {
  const p = mode === 'light' ? LIGHT : DARK
  return [
    `# ${STAMP}`,
    `# brand.yml (https://posit-dev.github.io/brand-yml/) — the ${mode} palette.`,
    'meta:',
    '  name: chromokit',
    `  link: ${REPO}`,
    'color:',
    '  palette:',
    `    blue: "${p.accent}"`,
    `    green: "${p.ok}"`,
    `    orange: "${p.warn}"`,
    `    red: "${p.danger}"`,
    `    gray: "${p['text-dim']}"`,
    `  background: "${p.bg}"`,
    `  foreground: "${p.text}"`,
    `  primary: "${p.accent}"`,
    `  secondary: "${p['text-dim']}"`,
    `  success: "${p.ok}"`,
    `  info: "${p.accent}"`,
    `  warning: "${p.warn}"`,
    `  danger: "${p.danger}"`,
    `  light: "${LIGHT['bg-sunken']}"`,
    `  dark: "${LIGHT.text}"`,
    'typography:',
    '  base:',
    `    family: ${JSON.stringify(app.base.sans)}`,
    `    size: ${kit.prose.size}`,
    `    line-height: ${kit.prose.line}`,
    '  headings:',
    '    weight: 600',
    '    color: foreground',
    '  monospace:',
    `    family: ${JSON.stringify(app.base.mono)}`,
    '    size: 0.875em',
    '  link:',
    '    color: primary',
    'defaults:',
    '  bootstrap:',
    '    defaults:',
    `      border-radius: ${app.base.radius}`,
    `      border-color: "${p.border}"`,
    '',
  ].join('\n')
}
emit('dist/brand/_brand.yml', brand('light'))
emit('dist/brand/_brand-dark.yml', brand('dark'))

// ---------------------------------------------------------------- plots

const mpl = (mode) => {
  const p = mode === 'light' ? LIGHT : DARK
  const bare = (hex) => hex.replace('#', '')
  return [
    `# ${STAMP}`,
    `# matplotlib style, ${mode}: plt.style.use("chromokit-${mode}.mplstyle") — or its URL.`,
    `figure.facecolor: ${bare(p.bg)}`,
    `figure.edgecolor: ${bare(p.bg)}`,
    `savefig.facecolor: ${bare(p.bg)}`,
    `axes.facecolor: ${bare(p.bg)}`,
    `axes.edgecolor: ${bare(p['border-strong'])}`,
    `axes.labelcolor: ${bare(p.text)}`,
    `axes.titlecolor: ${bare(p.text)}`,
    'axes.titleweight: 600',
    'axes.titlelocation: left',
    'axes.titlesize: 12',
    'axes.labelsize: 10',
    'axes.linewidth: 0.8',
    'axes.spines.top: False',
    'axes.spines.right: False',
    'axes.grid: True',
    'axes.axisbelow: True',
    `axes.prop_cycle: cycler('color', [${kit.categorical[mode].map((c) => `'${bare(c)}'`).join(', ')}])`,
    `grid.color: ${bare(p.border)}`,
    'grid.linewidth: 0.6',
    'grid.alpha: 0.7',
    `xtick.color: ${bare(p['text-dim'])}`,
    `ytick.color: ${bare(p['text-dim'])}`,
    `xtick.labelcolor: ${bare(p['text-dim'])}`,
    `ytick.labelcolor: ${bare(p['text-dim'])}`,
    'xtick.labelsize: 9',
    'ytick.labelsize: 9',
    `text.color: ${bare(p.text)}`,
    'font.family: sans-serif',
    'font.sans-serif: Inter, Segoe UI, Roboto, Helvetica Neue, Arial, DejaVu Sans, sans-serif',
    'font.monospace: JetBrains Mono, SF Mono, Menlo, Consolas, DejaVu Sans Mono, monospace',
    'font.size: 10',
    'legend.frameon: False',
    'legend.fontsize: 9',
    `legend.labelcolor: ${bare(p.text)}`,
    'lines.linewidth: 1.6',
    'patch.edgecolor: none',
    'image.cmap: Blues' + (mode === 'dark' ? '_r' : ''),
    '',
  ].join('\n')
}
emit('dist/plots/chromokit-light.mplstyle', mpl('light'))
emit('dist/plots/chromokit-dark.mplstyle', mpl('dark'))

const axis = (p) => ({
  axisLine: { show: true, lineStyle: { color: p['border-strong'] } },
  axisTick: { show: true, lineStyle: { color: p['border-strong'] } },
  axisLabel: { color: p['text-dim'] },
  splitLine: { show: true, lineStyle: { color: p.border, type: 'dashed' } },
  nameTextStyle: { color: p['text-dim'] },
})
const echarts = (mode) => {
  const p = mode === 'light' ? LIGHT : DARK
  return {
    color: kit.categorical[mode],
    backgroundColor: 'transparent',
    textStyle: { fontFamily: app.base.sans, color: p.text },
    title: { textStyle: { color: p.text, fontWeight: 600 }, subtextStyle: { color: p['text-dim'] } },
    legend: { textStyle: { color: p['text-dim'] } },
    tooltip: {
      backgroundColor: p['bg-raised'],
      borderColor: p['border-strong'],
      textStyle: { color: p.text },
    },
    categoryAxis: axis(p),
    valueAxis: axis(p),
    logAxis: axis(p),
    timeAxis: axis(p),
  }
}
emit('dist/plots/echarts-light.json', `${JSON.stringify(echarts('light'), null, 2)}\n`)
emit('dist/plots/echarts-dark.json', `${JSON.stringify(echarts('dark'), null, 2)}\n`)

const plotly = (mode) => {
  const p = mode === 'light' ? LIGHT : DARK
  const ax = { gridcolor: p.border, linecolor: p['border-strong'], zerolinecolor: p.border, tickcolor: p['border-strong'] }
  return {
    layout: {
      colorway: kit.categorical[mode],
      paper_bgcolor: p.bg,
      plot_bgcolor: p.bg,
      font: { family: app.base.sans, color: p.text },
      title: { x: 0, font: { size: 15 } },
      xaxis: ax,
      yaxis: ax,
      legend: { bgcolor: 'rgba(0,0,0,0)' },
      hoverlabel: { bgcolor: p['bg-raised'], bordercolor: p['border-strong'], font: { color: p.text } },
    },
  }
}
emit('dist/plots/plotly-light.json', `${JSON.stringify(plotly('light'), null, 2)}\n`)
emit('dist/plots/plotly-dark.json', `${JSON.stringify(plotly('dark'), null, 2)}\n`)

// ---------------------------------------------------------------- icons

const ICONS = json('src/icons.json')
const lucideDir = join(ROOT, 'node_modules', 'lucide-static', 'icons')
const simpleDir = join(ROOT, 'node_modules', 'simple-icons', 'icons')
const iconInner = {}
const haveIconPackages = existsSync(lucideDir) && existsSync(simpleDir)
for (const name of ICONS.lucide) {
  if (!haveIconPackages) break
  const svg = readFileSync(join(lucideDir, `${name}.svg`), 'utf8')
  iconInner[name] = svg
    .replace(/<!--[\s\S]*?-->/, '')
    .replace(/^[\s\S]*?<svg[^>]*>/, '')
    .replace(/<\/svg>[\s\S]*$/, '')
    .replace(/\s*\n\s*/g, '')
    .trim()
}
for (const [name, slug] of Object.entries(ICONS.brands)) {
  if (!haveIconPackages) break
  const svg = readFileSync(join(simpleDir, `${slug}.svg`), 'utf8')
  const path = svg.match(/<path d="([^"]+)"/)[1]
  iconInner[name] = `<path d="${path}" fill="currentColor" stroke="none"/>`
}
if (haveIconPackages) {
  const open = (name) =>
    ICONS.brands[name]
      ? '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" class="cx-icon cx-icon--filled" aria-hidden="true">'
      : '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cx-icon" aria-hidden="true">'
  const names = Object.keys(iconInner).sort()
  for (const name of names) emit(`dist/icons/${name}.svg`, `${open(name)}${iconInner[name]}</svg>\n`)
  emit(
    'dist/icons/sprite.svg',
    `<svg xmlns="http://www.w3.org/2000/svg" style="display:none">\n${names
      .map((name) =>
        ICONS.brands[name]
          ? `<symbol id="cx-${name}" viewBox="0 0 24 24" fill="currentColor">${iconInner[name]}</symbol>`
          : `<symbol id="cx-${name}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${iconInner[name]}</symbol>`,
      )
      .join('\n')}\n</svg>\n`,
  )
  emit('dist/icons/icons.json', `${JSON.stringify(Object.fromEntries(names.map((n) => [n, iconInner[n]])), null, 2)}\n`)
  emit(
    'dist/icons/LICENSES.md',
    '# Icon licences\n\nInterface icons are [Lucide](https://lucide.dev) (ISC licence, © Lucide Contributors).\nBrand marks are [Simple Icons](https://simpleicons.org) (CC0 1.0); each brand remains its owner\'s trademark.\n',
  )
} else if (!CHECK) {
  throw new Error('icons need `npm install` (lucide-static, simple-icons)')
}
/** An icon as inline SVG markup, for templates the build writes. */
const icon = (name, extra = '') => {
  const brandIcon = Boolean(ICONS.brands[name])
  const inner = iconInner[name] ?? (CHECK ? readIconFromDist(name) : undefined)
  if (inner === undefined) throw new Error(`unknown icon ${name}`)
  return brandIcon
    ? `<svg viewBox="0 0 24 24" fill="currentColor" class="cx-icon cx-icon--filled${extra}" aria-hidden="true">${inner}</svg>`
    : `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cx-icon${extra}" aria-hidden="true">${inner}</svg>`
}
function readIconFromDist(name) {
  const path = join(ROOT, 'dist', 'icons', 'icons.json')
  return existsSync(path) ? JSON.parse(readFileSync(path, 'utf8'))[name] : undefined
}
if (!haveIconPackages && CHECK) {
  // Without node_modules the check compares everything but the icons.
  for (const path of listFiles('dist/icons')) emit(path, readFileSync(join(ROOT, path)))
}

// ---------------------------------------------------------------- marks

emit('dist/marks/chromokit.svg', markSvg({ name: 'chromokit', style: 'genomes', cells: 7 }))

// ---------------------------------------------------------------- adapters

const ADAPTERS = {}

/** Zensical / Material for MkDocs: template overrides, one stylesheet, the keys. */
ADAPTERS.zensical = () => {
  for (const path of listFiles('adapters/zensical/overrides')) {
    emit(`dist/zensical/${relative('adapters/zensical', path)}`, read(path))
  }
  // The adapter before the components: its typeset rules (`.md-typeset a`)
  // must not repaint a component that is a link.
  emit('dist/zensical/stylesheets/chromokit.css', bundle(tokensCss, read('adapters/zensical/zensical.css'), componentsCss))
  emit('dist/zensical/javascripts/chromokit.js', `${jsHeader}${keys}`)
}

/** Astro Starlight: a plugin, its components, one stylesheet, the keys. */
ADAPTERS.starlight = () => {
  emit('dist/starlight/index.mjs', `${jsHeader}${read('adapters/starlight/index.mjs')}`)
  emit('dist/starlight/chromokit.css', bundle(tokensCss, componentsCss, read('adapters/starlight/starlight.css')))
  for (const path of listFiles('adapters/starlight/components')) {
    emit(`dist/starlight/${relative('adapters/starlight', path)}`, read(path))
  }
  emit('dist/starlight/components/keys.js', `${jsHeader}${keys}`)
}

/**
 * pkgdown: one Sass file pkgdown compiles into Bootstrap (`pkgdown/extra.scss`,
 * or a template package's `inst/pkgdown/BS5/extra.scss`), and the
 * `_pkgdown.yml` settings it expects. libsass, which R's sass package uses,
 * evaluates `rgb()`, `min()` and `max()` itself, so the file must not use them.
 */
ADAPTERS.pkgdown = () => {
  const scss = bundle(tokensCss, componentsCss, read('adapters/pkgdown/pkgdown.css'))
  const unsafe = scss.replace(/\/\*[\s\S]*?\*\//g, '').split('\n').filter((line) => /\brgba?\([^)]*\/|[^-\w](min|max)\(/.test(line))
  if (unsafe.length > 0) throw new Error(`not libsass-safe:\n${unsafe.join('\n')}`)
  emit('dist/pkgdown/extra.scss', scss.replace(/^\/\*! /, '// ').replace(/^(\/\/ .*?) \*\/\n/, '$1\n'))
  emit('dist/pkgdown/_pkgdown.yml', pkgdownYaml())
  emit('r/inst/pkgdown/BS5/extra.scss', outputs.get('dist/pkgdown/extra.scss'))
  emit('r/inst/pkgdown/_pkgdown.yml', pkgdownYaml())
}

/** The settings a pkgdown site needs for chromokit: Bootstrap 5, the light switch, the palette for Bootstrap's own Sass. */
function pkgdownYaml() {
  return [
    `# ${STAMP}`,
    'template:',
    '  bootstrap: 5',
    '  light-switch: true',
    '  theme: arrow-light',
    '  theme-dark: arrow-dark',
    '  bslib:',
    `    bg: "${LIGHT.bg}"`,
    `    fg: "${LIGHT.text}"`,
    `    primary: "${LIGHT.accent}"`,
    `    secondary: "${LIGHT['text-dim']}"`,
    `    success: "${LIGHT.ok}"`,
    `    warning: "${LIGHT.warn}"`,
    `    danger: "${LIGHT.danger}"`,
    `    border-radius: ${app.base.radius}`,
    `    border-color: "${LIGHT.border}"`,
    '    font-size-base: 1rem',
    '',
  ].join('\n')
}

/**
 * Quarto: an extension (`quarto add js2264/chromokit`) with an HTML format and
 * a revealjs one. Each palette is a theme file: Bootstrap's defaults from the
 * tokens, then chromokit's rules, which Quarto compiles with dart-sass.
 */
ADAPTERS.quarto = () => {
  const rules = [tokensCss, componentsCss, read('adapters/quarto/quarto.css')]
    .map((part) => part.replace(/^\/\*![^\n]*\*\/\n/, '').trim())
    .join('\n\n')
  const defaults = (p) =>
    [
      `$body-bg: ${p.bg};`,
      `$body-color: ${p.text};`,
      `$primary: ${p.accent};`,
      `$secondary: ${p['text-dim']};`,
      `$success: ${p.ok};`,
      `$warning: ${p.warn};`,
      `$danger: ${p.danger};`,
      `$info: ${p.accent};`,
      `$link-color: ${p.accent};`,
      `$border-color: ${p.border};`,
      `$border-radius: ${app.base.radius};`,
      `$font-family-sans-serif: ${app.base.sans};`,
      `$font-family-monospace: ${app.base.mono};`,
      '$font-size-root: 16px;',
      '$headings-font-weight: 600;',
      `$code-color: ${p.text};`,
      `$code-bg: ${p['bg-sunken']};`,
      `$code-block-bg: ${p['code-bg']};`,
      `$code-block-border-left: false;`,
      `$navbar-bg: ${p['bg-raised']};`,
      `$navbar-fg: ${p['text-dim']};`,
      `$navbar-hl: ${p.text};`,
      `$sidebar-bg: ${p['bg-raised']};`,
      `$sidebar-fg: ${p['text-dim']};`,
      `$sidebar-hl: ${p.text};`,
      `$footer-bg: ${p.bg};`,
      `$footer-fg: ${p['text-faint']};`,
      `$toc-color: ${p.accent};`,
      `$callout-border-width: 3px;`,
      `$table-border-color: ${p.border};`,
    ].join('\n')
  const theme = (mode) =>
    [
      `// ${STAMP}`,
      `// Quarto theme, ${mode} palette.`,
      '',
      '/*-- scss:defaults --*/',
      defaults(mode === 'light' ? LIGHT : DARK),
      '',
      '/*-- scss:rules --*/',
      rules,
      '',
    ].join('\n')
  const ext = '_extensions/chromokit'
  emit(`${ext}/_extension.yml`, read('adapters/quarto/_extension.yml').replace('{{version}}', VERSION))
  emit(`${ext}/chromokit-light.scss`, theme('light'))
  emit(`${ext}/chromokit-dark.scss`, theme('dark'))
  emit(
    `${ext}/chromokit-reveal.scss`,
    [
      `// ${STAMP}`,
      '// reveal.js theme: the light palette, system fonts, framed code.',
      '',
      '/*-- scss:defaults --*/',
      `$body-bg: ${LIGHT.bg};`,
      `$body-color: ${LIGHT.text};`,
      `$link-color: ${LIGHT.accent};`,
      `$selection-bg: ${LIGHT['accent-soft']};`,
      `$presentation-heading-color: ${LIGHT.text};`,
      `$presentation-heading-font: ${app.base.sans};`,
      '$presentation-heading-font-weight: 650;',
      `$font-family-sans-serif: ${app.base.sans};`,
      `$font-family-monospace: ${app.base.mono};`,
      `$code-block-bg: ${LIGHT['bg-sunken']};`,
      `$code-block-border-color: ${LIGHT.border};`,
      `$code-color: ${LIGHT.text};`,
      `$code-bg: ${LIGHT['bg-sunken']};`,
      `$border-radius: ${app.base.radius};`,
      '',
      '/*-- scss:rules --*/',
      tokensCss.replace(/^\/\*![^\n]*\*\/\n/, '').trim(),
      '',
      '.reveal .slide-background { background-image: radial-gradient(circle, color-mix(in srgb, var(--cx-border) 50%, transparent) 0.8px, transparent 1px); background-size: var(--cx-grain) var(--cx-grain); }',
      '.reveal h1, .reveal h2, .reveal h3 { letter-spacing: -0.02em; }',
      '.reveal pre { border: 1px solid var(--cx-border); border-radius: 8px; box-shadow: var(--cx-shadow-1); }',
      '.reveal .cx-kicker, .reveal .slide-subtitle { font: 600 0.5em / 1.2 var(--cx-sans); letter-spacing: 0.12em; text-transform: uppercase; color: var(--cx-accent); }',
      '',
    ].join('\n'),
  )
  emit(`${ext}/chromokit.html`, `<script>\n${jsHeader}${keys}\n${behaviours}</script>\n`)
  emit(`${ext}/chromokit-mark.svg`, outputs.get('dist/marks/chromokit.svg'))
}

/** Hugo: a theme (themes/chromokit) — layouts, shortcodes, the page stylesheet, the scripts, the icons as data. */
ADAPTERS.hugo = () => {
  for (const path of listFiles('adapters/hugo')) {
    if (path.endsWith('hugo.css')) continue
    emit(`dist/hugo/${relative('adapters/hugo', path)}`, read(path))
  }
  emit('dist/hugo/static/chromokit/chromokit.css', bundle(tokensCss, componentsCss, pageCss, read('adapters/hugo/hugo.css')))
  emit('dist/hugo/static/chromokit/theme.js', jsHeader + theme)
  emit('dist/hugo/static/chromokit/chromokit.js', `${jsHeader}${keys}\n${behaviours}`)
  emit(
    'dist/hugo/data/chromokit_icons.json',
    `${JSON.stringify(Object.fromEntries(Object.keys(iconInner).sort().map((name) => [name, icon(name)])), null, 2)}\n`,
  )
}

for (const [name, build] of Object.entries(ADAPTERS)) {
  try {
    build()
  } catch (error) {
    error.message = `adapter ${name}: ${error.message}`
    throw error
  }
}

// ---------------------------------------------------------------- the R package's tokens

{
  const rList = (values) =>
    Object.entries(values)
      .filter(([name]) => !name.startsWith('shadow'))
      .map(([name, value]) => `    "${name}" = "${value}"`)
      .join(',\n')
  const rVector = (values) => `c(${values.map((v) => `"${v}"`).join(', ')})`
  emit(
    'r/R/tokens.R',
    [
      `# ${STAMP.replace(/·/g, '-').replace(/—/g, '-')}`,
      '',
      `.cx_tokens <- list(`,
      `  version = "${VERSION}",`,
      `  light = list(\n${rList(LIGHT)}\n  ),`,
      `  dark = list(\n${rList(DARK)}\n  ),`,
      `  series = list(light = ${rVector(kit.categorical.light)}, dark = ${rVector(kit.categorical.dark)})`,
      ')',
      '',
    ].join('\n'),
  )
}

// ---------------------------------------------------------------- write or check

const stale = []
for (const root of OWNED) {
  const absolute = join(ROOT, root)
  if (!existsSync(absolute)) continue
  const files = statSync(absolute).isDirectory() ? listFiles(root) : [root]
  for (const path of files) if (!outputs.has(path)) stale.push(path)
}

if (CHECK) {
  const changed = []
  for (const [path, contents] of outputs) {
    const absolute = join(ROOT, path)
    const current = existsSync(absolute) ? readFileSync(absolute) : null
    const next = Buffer.isBuffer(contents) ? contents : Buffer.from(contents)
    if (current === null || !current.equals(next)) changed.push(path)
  }
  if (changed.length > 0 || stale.length > 0) {
    for (const path of changed) console.error(`out of date: ${path}`)
    for (const path of stale) console.error(`stale: ${path}`)
    console.error('\nRun `npm run build` and commit the result.')
    process.exit(1)
  }
  console.log(`up to date: ${outputs.size} files`)
} else {
  for (const path of stale) rmSync(join(ROOT, path))
  for (const [path, contents] of outputs) {
    const absolute = join(ROOT, path)
    mkdirSync(dirname(absolute), { recursive: true })
    writeFileSync(absolute, contents)
  }
  console.log(`wrote ${outputs.size} files${stale.length > 0 ? `, removed ${stale.length} stale` : ''}`)
}

export { ADAPTERS, LIGHT, DARK, base, icon, outputs }
